import re

# Read the dictionary file
valid_words = set()
with open('/workdir/data/dict.txt', 'r') as f:
    for line in f:
        word = line.strip()
        if re.match(r'^[a-zA-Z]+$', word):
            word_lower = word.lower()
            valid_words.add(word_lower)

# Test simple shift mapping first to see stats
mapping = {}
for i in range(26):
    original = chr(ord('a') + i)
    mapped = chr(ord('a') + ((i + 1) % 26))
    mapping[original] = mapped

matches = []
for word in valid_words:
    if len(word) >= 4:
        transformed = ''.join(mapping[c] for c in word)
        if transformed in valid_words:
            matches.append(word)

print(f"Total matches with shift mapping: {len(matches)}")
# Check unique chars in all matches
chars_all = set()
for w in matches:
    chars_all.update(w)
print(f"Unique chars in ALL matches: {len(chars_all)}")
print("All matching words:")
for w in matches[:50]:
    print(w)
EOF
